tn.on('spend', async (m) => { if (typeof m.req === 'string' && waiting.has(m.req)) { const f = waiting.get(m.req); waiting.delete(m.req); f(m); return; }
  const ch = CH.find((c) => c.id === m.req); if (!ch) return; spendAsked.delete(ch.id); if (!m.found) return; try { await P.onSpend(ch, { txid: m.txid, height: m.height, blockHash: m.blockHash ?? null, hex: m.hex }); } catch (e) { log(`spend of ${ch.id}: ${e.message}`, 'e'); } });
let following = false;
tn.on('synced', async () => { if (!W || !P) return; watch(); if (!node.mempoolOn) { node.mempoolOn = true; tn.followMempool({ relays: OPT.relays }); } if (following) return; following = true; try { for (const ch of CH) if (FOLLOWING.has(ch.status)) await P.afterClose(ch).catch((e) => log(e.message, 'e')); } finally { following = false; } });

// ---- invoices: hitch1 + base64url of { p: node id, a: sats, m: memo, h: hash, r: hubs, f: hub fee, x: expires, i: id }; the preimage stays with the issuer
const b64u = (s) => btoa(unescape(encodeURIComponent(s))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); const unb64u = (s) => decodeURIComponent(escape(atob(s.replace(/-/g, '+').replace(/_/g, '/'))));
function makeInvoice(amount, memo) { if (!Number.isInteger(amount) || amount < 1000) throw new Error('at least 1,000 sat, a whole number'); const hubs = CH.filter((c) => c.status === 'open' && c.peerHubFee != null); const { preimage, inv } = P.invoice(amount, memo, [...new Set(hubs.map((c) => c.peer))], hubs.reduce((a, c) => Math.max(a, c.peerHubFee), 0)); INV.set(inv.h, { preimage, amount, memo: memo || undefined, x: inv.x }); saveInv(); return 'hitch1' + b64u(JSON.stringify(inv)); }
function parseInvoice(s) { s = s.trim(); if (!s.startsWith('hitch1')) throw new Error('not a Hitch invoice'); const inv = JSON.parse(unb64u(s.slice(6))); if (!/^[0-9a-f]{64}$/.test(inv.p ?? '') || !Number.isInteger(inv.a) || inv.a < 1 || !/^[0-9a-f]{64}$/.test(inv.h ?? '') || (inv.r != null && !(Array.isArray(inv.r) && inv.r.every((x) => /^[0-9a-f]{64}$/.test(x)))) || (inv.f != null && !(Number.isInteger(inv.f) && inv.f >= 0)) || (inv.x != null && !Number.isInteger(inv.x)) || (inv.m != null && !(typeof inv.m === 'string' && inv.m.length <= 140))) throw new Error('bad invoice'); return inv; }

// ---- rendering
const stLabel = (s) => ({ proposed: ['proposed', 'pend'], accepted: ['accepted, waiting for their signature', 'pend'], funding: ['funding, waiting for a block', 'pend'], open: ['open', 'open'], 'closing-asked': ['close asked', 'pend'], closing: ['closing', 'pend'], 'force-closing': ['force closing', 'pend'], 'closed-mine': ['closed by me, delay running', 'pend'], 'closed-coop': ['closed cooperatively, final after 6 blocks', 'pend'], 'closed-theirs': ['closed by them, claims running', 'pend'], 'closed-theirs-alt': ['closed by them at a state I had signed, claims running', 'pend'], closed: ['closed', 'closed'], settling: ['closed, claims confirming', 'pend'], unfunded: ['funding never confirmed; opens if it does', 'bad'], punishing: ['punishing a cheat', 'bad'], punished: ['closed: their cheat punished', 'closed'], 'spent-unknown': ['spent by an unknown transaction', 'bad'], 'bad-funding': ['funding output does not match: refused', 'bad'], abandoned: ['abandoned: never funded', 'closed'] }[s] ?? [s, '']);
const link = (txid, text) => `<a href="${EXPLORER}/tx/${esc(txid)}" target="_blank" rel="noopener" title="${esc(txid)}">${esc(text)}</a>`;
function renderChannels() { const el = $('chlist'); el.innerHTML = CH.length ? CH.slice().reverse().map((ch) => { const tot = ch.funding.value; const mine = myBal(ch), theirs = theirBal(ch); const [lbl0, cls] = stLabel(ch.status); const lbl = ch.cancelTxid && ['funding', 'unfunded'].includes(ch.status) ? (ch.cancelConfirmed ? 'funding cancelled, coins back' : 'funding being cancelled') : lbl0; const inflight = P.htlcs(ch);
    const note = ch.pending ? ' · update pending' : ch.awaiting ? ' · waiting for their revocation' : ''; const links = [link(ch.funding.txid, 'funding'), ch.cancelTxid ? link(ch.cancelTxid, 'cancel') : '', ch.closeTxid ? link(ch.closeTxid, 'close') : '', ch.coopTxid && ch.coopTxid !== ch.closeTxid ? link(ch.coopTxid, 'cooperative close') : '', ...(ch.penalties ?? []).map((p, i) => link(p, `penalty${ch.penalties.length > 1 ? ' ' + (i + 1) : ''}`)), ...Object.entries(ch.claimed ?? {}).map(([k2, v]) => link(v, k2.split(' ')[0]))].filter(Boolean).join(' · ');
    const buttons = ch.status === 'open' ? `<button class="q" data-act="close" data-ch="${esc(ch.id)}">Close</button><button class="q" data-act="force" data-ch="${esc(ch.id)}">Force close…</button>${OPT.dev && ch.n > 0 ? `<button class="q danger" data-act="cheat" data-ch="${esc(ch.id)}">Cheat (test)…</button>` : ''}` : ['closing-asked', 'closing'].includes(ch.status) ? `<button class="q" data-act="force" data-ch="${esc(ch.id)}">Force close…</button>` : (ch.status === 'unfunded' || (ch.status === 'funding' && now() - (ch.broadcastAt ?? now()) > 3600)) && ch.role === 'a' && ch.funding.inputs?.length && !ch.cancelTxid ? `<button class="q" data-act="cancel" data-ch="${esc(ch.id)}">Cancel the funding…</button>` : '';
    const forget = TERMINAL.has(ch.status) || (['unfunded', 'funding'].includes(ch.status) && (ch.role === 'b' ? ch.status === 'unfunded' : !!ch.cancelConfirmed)) ? `<button class="q" data-act="forget" data-ch="${esc(ch.id)}">Forget…</button>` : `<button class="q" data-act="abandon" data-ch="${esc(ch.id)}" title="remove from this tab; read the warning first">Abandon…</button>`;
    return `<div class="chan"><div class="hd"><b>${esc(ch.id)}</b><span class="st ${cls}">${esc(lbl)}</span><span class="mut">with ${esc(ch.peer.slice(0, 12))}… · ${ch.role === 'a' ? 'I funded' : 'they funded'} ${sats(tot)} · state ${ch.n}${ch.conf ? ` · ${ch.conf} conf` : ''}${esc(note)}${inflight.length ? ` · ${inflight.length} htlc in flight (${sats(inflight.reduce((a, h) => a + h.amount, 0))})` : ''}${ch.role === 'b' && ch.peerHubFee != null ? ' · a hub' : ''}</span></div>
    <div class="bar2" title="mine ${sats(mine)} · theirs ${sats(theirs)}"><i style="width:${(mine / tot * 100).toFixed(1)}%"></i><i class="r" style="width:${(theirs / tot * 100).toFixed(1)}%"></i></div>
    <div class="row" style="margin-top:6px;font-size:12px"><span>mine <b class="mono">${sats(mine)}</b></span><span class="mut">theirs ${sats(theirs)}</span><span class="mut">${links}</span><span class="fill" style="flex:1"></span>${buttons}${forget}</div></div>`; }).join('') : '<div class="mut">no channels yet: open one to another node id, or wait for one to be opened to you</div>';
  el.querySelectorAll('button[data-act]').forEach((b) => { b.onclick = async () => { const ch = byId(b.dataset.ch); if (!ch) return; try {
    if (b.dataset.act === 'close') await closeChannel(ch);
    else if (b.dataset.act === 'force') { const fl = P.htlcs(ch); if (await ask('Force close', [`This publishes your latest commitment (state ${ch.n}). Your ${sats(myBal(ch))} come back to your key after ${ch.delay} blocks (${hours(ch.delay)}); theirs at once. It costs ${sats(ch.fee)} in fees.`, ...(fl.length ? [`${fl.length} HTLC(s) in flight (${sats(fl.reduce((a, h) => a + h.amount, 0))}) are settled on the chain: claimed with the preimage or refunded after their expiry; keep the tab open until they are.`] : []), ...(ch.pending ? ['The update that is pending is set aside; if the other side acknowledged it late it could still take effect.'] : []), 'Use it when the other side is gone. A cooperative close is cheaper and faster when they answer.'], 'Force close', true)) await forceClose(ch); }
    else if (b.dataset.act === 'cheat') { if (await ask('Cheat, for the test', [`This publishes an OLD state (${ch.n - 1}) that you have revoked. If the other side is watching, it takes the whole channel: you lose ${sats(myBal(ch))}.`, 'This exists to show that cheating is punished.'], 'Publish the revoked state', true)) await forceClose(ch, ch.n - 1, 'CHEATING'); }
    else if (b.dataset.act === 'forget') { if (await ask('Forget this channel?', [`It is ${stLabel(ch.status)[0]}. Its record leaves this tab; export a backup first if you might need the details.`], 'Forget')) { CH.splice(CH.indexOf(ch), 1); io.save(); } }
    else if (b.dataset.act === 'cancel') await cancelFunding(ch);
    else if (b.dataset.act === 'abandon') { const lines = ch.status === 'closed-coop' ? [`It is ${stLabel(ch.status)[0]}. Until it is ${CLOSE_DEPTH} blocks deep a reorganisation could replace it with an old commitment, which this tab could then no longer punish.`, 'Wait for it to become closed, then Forget.'] : ['funding', 'unfunded'].includes(ch.status) && ch.role === 'a' ? [`It is ${stLabel(ch.status)[0]}. If the funding ever confirms after this record is gone, the ${sats(ch.funding.value)} are locked in a 2-of-2 output nobody can spend.`, 'Cancel the funding first (the button on the channel, an hour after the funding went out) and forget it once the cancel is confirmed.'] : [`It is ${stLabel(ch.status)[0]}. Removing it from this tab does not close it and does not return any funds.`, 'You lose the signed commitments and the revocation secrets: you can never force-close or claim from it again, and the other side can publish any old state without being punished.', 'Export a backup first if there is any doubt.']; if (await ask('Abandon this channel?', lines, 'Abandon', true)) { CH.splice(CH.indexOf(ch), 1); io.save(); } }
  } catch (e) { log(`${b.dataset.act} ${ch.id}: ${e.message}`, 'e'); } }; });
  $('push-ch').innerHTML = CH.filter((c) => c.status === 'open').map((c) => `<option value="${esc(c.id)}">${esc(c.id)} · mine ${sats(myBal(c))} · with ${esc(c.peer.slice(0, 10))}…</option>`).join('') || '<option value="">no open channel</option>';
  const busy = CH.some((c) => c.pending || c.awaiting || P.htlcs(c).length || CLOSED_OUT.has(c.status) || FOLLOWING.has(c.status)); const open = CH.filter((c) => c.status === 'open');
  $('keepopen').hidden = !busy && !open.length; $('keepopen').textContent = busy ? 'Keep this tab open: a payment is settling, an HTLC is in flight, or a close is being watched. A closed tab cannot punish a cheat or claim what is yours; both have deadlines measured in blocks.' : `A channel is open: come back to this tab well within ${hours(Math.max(1, Math.min(...open.map((c) => c.delay)) - 2))} each time (the channel delay, less the time a penalty needs to confirm). An old state published while the tab is closed for longer goes unpunished.`; renderBalances(); }
function renderBalances() { if (!W || !P) return; const open = CH.filter((c) => c.status === 'open'); const spendable = open.reduce((a, c) => a + (c.pending || c.awaiting ? 0 : Math.max(0, P.room(c))), 0), remote = open.reduce((a, c) => a + theirBal(c), 0);
  const inflight = open.reduce((a, c) => a + P.htlcs(c).filter((h) => h.from === c.role).reduce((x, h) => x + h.amount, 0), 0); const settling = CH.filter((c) => ['closing-asked', 'closing', 'force-closing', 'closed-mine', 'closed-theirs', 'closed-theirs-alt', 'punishing', 'settling'].includes(c.status)).reduce((a, c) => a + myBal(c), 0);
  let avail = 0, imm = 0; for (const c of W.coins) (mature(c) ? (avail += c.value) : (imm += c.value));
  const opening = CH.filter((c) => ['proposed', 'accepted', 'funding', 'unfunded'].includes(c.status) && c.role === 'a').reduce((a, c) => a + c.funding.value, 0);
  $('ch-local').textContent = money(spendable); $('ch-remote').textContent = money(remote); $('ch-flight').textContent = money(inflight); $('ch-settling').textContent = money(settling); $('ch-opening').textContent = money(opening); $('avail').textContent = money(avail); $('immature').textContent = money(imm); $('ch-count').textContent = `${open.length} open, ${CH.length} in all`; }
function render() { if (P) renderChannels(); else if (!SOLE) renderReadOnly(); }
function renderReadOnly() { $('chlist').innerHTML = CH.length ? CH.slice().reverse().map((ch) => `<div class="chan"><div class="hd"><b>${esc(ch.id)}</b><span class="st ${stLabel(ch.status)[1]}">${esc(stLabel(ch.status)[0])}</span><span class="mut">read-only: the other tab runs this channel</span></div></div>`).join('') : '<div class="mut">no channels</div>'; }
addEventListener('beforeunload', (e) => { if (!P) return; const busy = CH.some((c) => c.pending || c.awaiting || P.htlcs(c).length || CLOSED_OUT.has(c.status) || FOLLOWING.has(c.status)); if (busy) { e.preventDefault(); e.returnValue = ''; } });

// ---- the page
document.querySelectorAll('.tool button[data-p]').forEach((b) => { b.onclick = () => { document.querySelectorAll('.tool button[data-p]').forEach((x) => x.classList.toggle('on', x === b)); document.querySelectorAll('.page').forEach((p) => p.classList.toggle('on', p.id === 'p-' + b.dataset.p)); }; });
document.querySelectorAll('#menu > div').forEach((m) => { m.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); m.click(); m.querySelector('.dd > div')?.focus(); } else if (e.key === 'Escape') m.classList.remove('open'); }; m.querySelectorAll('.dd > div').forEach((it) => { it.setAttribute('role', 'menuitem'); it.tabIndex = 0; it.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); it.click(); } else if (e.key === 'Escape') { m.classList.remove('open'); m.focus(); } }; }); m.onclick = (e) => { const open = m.classList.contains('open'); document.querySelectorAll('#menu > div').forEach((x) => x.classList.remove('open')); if (!open && !e.target.closest('.dd')) m.classList.add('open'); }; }); document.addEventListener('click', (e) => { if (!e.target.closest('#menu')) document.querySelectorAll('#menu > div').forEach((x) => x.classList.remove('open')); });
$('op-go').onclick = async () => { try { $('op-out').textContent = 'proposing…'; await openChannel($('op-peer').value.trim().toLowerCase(), Math.round(Number($('op-amt').value)), Math.round(Number($('op-push').value) || 0)); $('op-out').textContent = 'proposed; waiting for the other side'; } catch (e) { $('op-out').textContent = e.message; } };
$('push-go').onclick = async () => { try { const ch = byId($('push-ch').value); if (!ch) throw new Error('no open channel'); const amount = Math.round(Number($('push-amt').value)); if (!(await ask('Push to the channel', [`${sats(amount)} to ${ch.peer.slice(0, 16)}… on ${ch.id}, with no invoice: the other side just gets it.`], 'Push'))) return; await pay(ch, amount, $('push-memo').value.trim() || null); $('push-out').textContent = 'update sent; it is final when they acknowledge and you revoke'; } catch (e) { $('push-out').textContent = e.message; } };
$('pay-go').onclick = async () => { try { const inv = parseInvoice($('pay-inv').value); if (['sent', 'in flight'].includes(payRecord(inv.h)?.status)) throw new Error(`that invoice is already ${payRecord(inv.h).status} from this tab`); const r = await payInvoice(inv); $('pay-out').dataset.hash = inv.h; $('pay-out').textContent = `paying ${sats(r.amount)} on ${r.ch.id}${r.via ? ` through ${r.via.slice(0, 12)}…` : ''}: the HTLC is out; the outcome shows here and in the list below`; } catch (e) { $('pay-out').dataset.hash = ''; $('pay-out').textContent = e.message; } };
$('pay-paste').onclick = async () => { try { $('pay-inv').value = await navigator.clipboard.readText(); } catch {} };
$('inv-go').onclick = () => { try { const s = makeInvoice(Math.round(Number($('inv-amt').value)), $('inv-memo').value.trim()); $('inv-out').value = s; const qr = qrcode(0, 'M'); qr.addData(s); qr.make(); $('inv-qr').innerHTML = qr.createSvgTag({ cellSize: 3, margin: 0 }); } catch (e) { $('inv-out').value = e.message; } };
$('inv-copy').onclick = async () => { try { await navigator.clipboard.writeText($('inv-out').value); $('inv-copy').textContent = 'Copied'; setTimeout(() => { $('inv-copy').textContent = 'Copy'; }, 1500); } catch {} };
$('m-nodeid').onclick = async () => { try { await navigator.clipboard.writeText(W.pub); notify('Copied', 'this node id is on the clipboard'); } catch {} };
$('m-readme').onclick = () => window.open('https://github.com/bitcoin-blake/hitch#readme', '_blank', 'noopener'); $('m-source').onclick = () => window.open('https://github.com/bitcoin-blake/hitch', '_blank', 'noopener');
$('m-about').onclick = () => $('about').showModal(); $('about-ok').onclick = () => $('about').close();
// ---- the window: dragged by its title bar, resized at any edge, zoomed by the green dot; geometry remembered; the tray when closed or minimized
const win = $('win'); const embedded = q.get('embedded') === '1' || q.get('frame') === '0';
const geom = { get: () => { try { return JSON.parse(LS.get('hitch:geometry') ?? 'null'); } catch { return null; } }, set: (g) => LS.set('hitch:geometry', JSON.stringify(g)) };
function applyGeometry(g) { win.style.left = g.x + 'px'; win.style.top = g.y + 'px'; win.style.width = g.w + 'px'; win.style.height = g.h + 'px'; }
function clampGeometry(g) { const W = innerWidth, H = innerHeight; g.w = Math.max(720, Math.min(g.w, W)); g.h = Math.max(420, Math.min(g.h, H)); g.x = Math.max(0, Math.min(g.x, W - Math.min(g.w, 120))); g.y = Math.max(0, Math.min(g.y, H - 40)); return g; }
function defaultGeometry() { const w = Math.min(1180, innerWidth - 48), h = Math.min(780, innerHeight - 48); return { x: Math.round((innerWidth - w) / 2), y: Math.round((innerHeight - h) / 2), w, h }; }
function layoutWindow() { if (embedded) return; const small = innerWidth < 1100 || innerHeight < 700; const saved = geom.get(); const max = saved?.max ?? small; win.classList.toggle('max', max); if (!max) applyGeometry(clampGeometry(saved?.g ?? defaultGeometry())); }
function saveGeometry() { if (embedded) return; const max = win.classList.contains('max'); const g = max ? (geom.get()?.g ?? defaultGeometry()) : { x: win.offsetLeft, y: win.offsetTop, w: win.offsetWidth, h: win.offsetHeight }; geom.set({ max, g }); }
function toggleZoom() { if (embedded) return; const max = !win.classList.contains('max'); win.classList.toggle('max', max); if (!max) applyGeometry(clampGeometry(geom.get()?.g ?? defaultGeometry())); saveGeometry(); }
if (!embedded) {
  layoutWindow(); addEventListener('resize', () => { if (!win.classList.contains('max')) applyGeometry(clampGeometry({ x: win.offsetLeft, y: win.offsetTop, w: win.offsetWidth, h: win.offsetHeight })); });
  $('dot-zoom').onclick = (e) => { e.stopPropagation(); toggleZoom(); }; $('wtitle').ondblclick = (e) => { if (!e.target.closest('.dots, .badge')) toggleZoom(); }; $('dot-close').onclick = (e) => { e.stopPropagation(); hideWindow(); }; $('dot-min').onclick = (e) => { e.stopPropagation(); hideWindow(); };
  // drag by the title bar
  $('wtitle').onpointerdown = (e) => { if (win.classList.contains('max') || e.target.closest('.dots, .badge')) return; const sx = e.clientX - win.offsetLeft, sy = e.clientY - win.offsetTop; const move = (ev) => applyGeometry(clampGeometry({ x: ev.clientX - sx, y: ev.clientY - sy, w: win.offsetWidth, h: win.offsetHeight })); const up = () => { removeEventListener('pointermove', move); removeEventListener('pointerup', up); saveGeometry(); }; addEventListener('pointermove', move); addEventListener('pointerup', up); e.preventDefault(); };
  // resize at any edge or corner
  win.querySelectorAll(':scope > .rs').forEach((h) => { h.onpointerdown = (e) => { if (win.classList.contains('max')) return; const d = h.dataset.rs, x0 = e.clientX, y0 = e.clientY, g0 = { x: win.offsetLeft, y: win.offsetTop, w: win.offsetWidth, h: win.offsetHeight };
    const move = (ev) => { const dx = ev.clientX - x0, dy = ev.clientY - y0; const g = { ...g0 }; if (d.includes('e')) g.w = g0.w + dx; if (d.includes('s')) g.h = g0.h + dy; if (d.includes('w')) { g.w = g0.w - dx; g.x = g0.x + dx; } if (d.includes('n')) { g.h = g0.h - dy; g.y = g0.y + dy; } if (g.w < 720) { if (d.includes('w')) g.x = g0.x + g0.w - 720; g.w = 720; } if (g.h < 420) { if (d.includes('n')) g.y = g0.y + g0.h - 420; g.h = 420; } applyGeometry(g); };
    const up = () => { removeEventListener('pointermove', move); removeEventListener('pointerup', up); saveGeometry(); }; addEventListener('pointermove', move); addEventListener('pointerup', up); e.preventDefault(); e.stopPropagation(); }; });
}

// ---- the tray: closing or minimizing the window keeps the node running and leaves a small card to come back through (Knots goes to the system tray the same way); inside Glass the host is told and keeps its dock
function hideWindow() { if (embedded) { try { parent.postMessage({ source: 'hitch', type: 'minimize' }, '*'); } catch {} return; } win.style.display = 'none'; unseen = 0; $('tray-badge').hidden = true; $('tray').hidden = false; trayRefresh(); }
function showWindow() { win.style.display = ''; $('tray').hidden = true; unseen = 0; $('tray-badge').hidden = true; }
function trayRefresh() { if ($('tray').hidden) return; const open = CH.filter((c) => c.status === 'open'); const sd = open.length ? ` · ${open.length} channel${open.length === 1 ? '' : 's'}, ${sats(open.reduce((a, c) => a + myBal(c), 0))}` : ''; $('tray-l').textContent = node.error ? 'error' : node.synced ? `up to date · ${n(node.height)}${sd}` : node.phase === 'fetch' ? 'fetching the snapshot' : node.phase === 'hash' ? 'checking the snapshot' : node.phase === 'verify' ? 'verifying the snapshot' : node.phase === 'sync' ? `syncing · ${n(node.height ?? 0)}` : 'starting'; $('tray-dot').className = node.error ? 'bad' : node.synced ? 'ok' : 'sync'; }
$('tray').onclick = () => showWindow(); $('tray').onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); showWindow(); } }; setInterval(trayRefresh, 1000);

