$('m-about').onclick = () => $('about').showModal(); $('about-ok').onclick = () => $('about').close();
$('m-options').onclick = () => { $('o-relays').value = OPT.relays.join('\n'); $('o-delay').value = OPT.delay; $('o-delayh').textContent = hours(OPT.delay); $('o-fee').value = OPT.fee; $('o-notify').checked = !!OPT.notify; $('o-dev').checked = !!OPT.dev; $('o-snapshot').value = SNAP_URL; $('o-blocks').value = BLOCKS_URL; $('o-address').value = W?.address ?? '…'; $('o-key').value = '•'.repeat(64); $('o-showkey').textContent = 'Show'; $('o-importkey').value = ''; $('o-keynote').textContent = W?.fromReef ? "Reef's key in this browser: back it up in Reef" : 'a key of this tab: copy it somewhere safe, the export below does not include it'; $('o-note').textContent = ''; $('options').showModal(); };
$('o-delay').oninput = () => { $('o-delayh').textContent = hours(Number($('o-delay').value) || 0); };
$('o-cancel').onclick = () => $('options').close();
$('o-showkey').onclick = () => { const shown = $('o-key').value !== '•'.repeat(64); $('o-key').value = shown ? '•'.repeat(64) : (W?.key ?? ''); $('o-showkey').textContent = shown ? 'Show' : 'Hide'; };
$('o-copykey').onclick = async () => { try { await navigator.clipboard.writeText(W?.key ?? ''); $('o-copykey').textContent = 'Copied'; setTimeout(() => { $('o-copykey').textContent = 'Copy'; }, 1500); } catch {} };
$('o-export').onclick = async () => { if (!(await ask('Export the channel documents', ['The file holds every signed commitment, every revocation secret and every preimage. Anyone who reads it can take what is yours in these channels. It does not hold the key.', 'Keep it where only you can read it.'], 'Export'))) return; const blob = new Blob([JSON.stringify({ hitch: 1, exported: now(), node: W.pub, channels: CH, invoices: [...INV] }, null, 1)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `hitch-channels-SECRET-${W.pub.slice(0, 8)}-${new Date().toISOString().slice(0, 10)}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000); };
$('o-import').onchange = async () => { const f = $('o-import').files[0]; if (!f) return; try { const d = JSON.parse(await f.text()); if (d.hitch !== 1 || !Array.isArray(d.channels)) throw new Error('not a Hitch backup'); if (d.node && d.node !== W.pub) throw new Error(`that backup is for node ${d.node.slice(0, 12)}…, this tab is ${W.pub.slice(0, 12)}…`); let added = 0, newer = 0; for (const c of d.channels) { const have = byId(c.id); if (!have) { CH.push(c); added++; } else if ((c.n ?? 0) > (have.n ?? 0)) { Object.assign(have, c); newer++; } } for (const [h, p] of d.invoices ?? []) if (!INV.has(h)) INV.set(h, typeof p === 'string' ? { preimage: p, amount: 0 } : p); saveInv(); io.save(); $('o-note').textContent = `imported: ${added} new channel(s), ${newer} brought forward; resyncing`; log(`backup imported: ${added} new, ${newer} newer`); P.resyncAll(true).catch(() => {}); } catch (e) { $('o-note').textContent = e.message; } };
$('o-ok').onclick = async () => { const relays = $('o-relays').value.split(/\s+/).filter((r) => /^wss?:\/\//.test(r)); OPT.relays = relays.length ? relays : DEFAULT_RELAYS; OPT.delay = Math.max(6, Math.min(144, Math.round(Number($('o-delay').value) || DEFAULT_DELAY))); OPT.fee = Math.max(100, Math.min(10000, Math.round(Number($('o-fee').value) || DEFAULT_FEE))); OPT.dev = $('o-dev').checked; const wantNotify = $('o-notify').checked; if (wantNotify && 'Notification' in window && Notification.permission === 'default') await Notification.requestPermission(); OPT.notify = wantNotify && Notification.permission === 'granted'; saveOptions();
  const s = $('o-snapshot').value.trim(), b = $('o-blocks').value.trim(); if (s) LS.set('hitch:snapshot', s); if (b) LS.set('hitch:blocks', b); const key = $('o-importkey').value.trim().toLowerCase(); if (key && !/^[0-9a-f]{64}$/.test(key)) { $('o-note').textContent = 'a key is 64 hex characters'; return; }
  if (key) { if (CH.some((c) => (LIVE.has(c.status) || WATCHED.has(c.status)) && c.keys[c.role] === W.pub)) { $('o-note').textContent = 'this tab has channels made with the current key that are open or still being watched; close and settle them first, or export them'; return; } if ($('o-key').value === '•'.repeat(64)) { $('o-note').textContent = 'show or copy the current key first: it is the only way back to it'; return; } if (!(await ask('Replace the key', ['The current key stays where it is (in Reef, if it is Reef\'s) but this tab stops using it. Channels in this tab that belong to another key cannot be signed for.'], 'Replace', true))) return; LS.set('hitch:key', key); LS.set('hitch:prefer', 'own'); }
  $('options').close(); location.search = embedded ? (q.get('frame') === '0' ? '?frame=0' : '?embedded=1') : ''; };
window.hitch = { tn, node, CH, INV, get W() { return W; }, get C() { return C; }, pay, openChannel, closeChannel, forceClose, payInvoice, makeInvoice };
// one tab of this origin runs the protocol; a second one would sign with its own fresh points over the same documents and wedge the channels
let SOLE = true; if (navigator.locks) { await new Promise((res) => navigator.locks.request('hitch:peer', { ifAvailable: true }, (lock) => { SOLE = !!lock; res(); return lock ? new Promise(() => {}) : undefined; }).catch(() => res())); }
try { await init(); if (SOLE) setupPeer(); else { $('twotabs').hidden = false; log('another tab of Hitch is running on this origin: this one is read-only (close the other one and reload to take over)', 'e'); document.querySelectorAll('#op-go, #push-go, #pay-go, #inv-go, #chlist').forEach((el) => { el.classList.add('ro'); }); } } catch (e) { log('could not start: ' + e.message, 'e'); }
if (!SOLE) addEventListener('storage', (e) => { if (e.key === 'hitch:channels') { try { const fresh = JSON.parse(e.newValue ?? '[]'); CH.splice(0, CH.length, ...fresh); } catch {} } });
document.querySelectorAll('label').forEach((l) => { if (l.htmlFor || l.querySelector('input')) return; const nx = l.nextElementSibling; const inp = nx?.matches?.('input,textarea,select') ? nx : nx?.querySelector?.('input,textarea,select'); if (inp?.id) l.htmlFor = inp.id; });
render(); renderRelays(); renderPayments(); log('Hitch started');
try { if (await tn.start() === false) $('syncmsg').textContent = 'idle: the node runs in another tab of this browser (Reef, Bight, Winch or Hitch); close that tab and reload here'; } catch (e) { $('syncmsg').textContent = 'Error: could not start the node: ' + e.message; }
